/** A half-open time interval [start, end). */
export type Interval = { start: Date | number; end: Date | number };
type Ms = { start: number; end: number };

const ms = (i: Interval): Ms => ({ start: +new Date(i.start), end: +new Date(i.end) });
const out = (i: Ms) => ({ start: new Date(i.start), end: new Date(i.end) });

/** Sorts and merges overlapping or touching intervals. */
export function mergeIntervals(intervals: readonly Interval[]): { start: Date; end: Date }[] {
  const sorted = intervals.map(ms).filter((i) => i.end > i.start).sort((a, b) => a.start - b.start);
  const merged: Ms[] = [];
  for (const i of sorted) {
    const last = merged[merged.length - 1];
    if (last && i.start <= last.end) last.end = Math.max(last.end, i.end);
    else merged.push({ ...i });
  }
  return merged.map(out);
}

/** The free time inside `within` once `busy` is taken out. */
export function subtractBusy(within: Interval, busy: readonly Interval[]): { start: Date; end: Date }[] {
  const w = ms(within);
  const free: Ms[] = [];
  let cursor = w.start;
  for (const b of mergeIntervals(busy).map(ms)) {
    if (b.end <= cursor) continue;
    if (b.start >= w.end) break;
    if (b.start > cursor) free.push({ start: cursor, end: Math.min(b.start, w.end) });
    cursor = Math.max(cursor, b.end);
  }
  if (cursor < w.end) free.push({ start: cursor, end: w.end });
  return free.map(out);
}

/**
 * When everyone is free: the intersection of each person's free intervals. The Interview
 * Scheduler's highlighted overlap.
 */
export function intersectAvailability(people: readonly (readonly Interval[])[]): { start: Date; end: Date }[] {
  if (!people.length) return [];
  let acc: Ms[] = mergeIntervals(people[0]).map(ms);
  for (const person of people.slice(1)) {
    const other = mergeIntervals(person).map(ms);
    const next: Ms[] = [];
    let i = 0;
    let j = 0;
    while (i < acc.length && j < other.length) {
      const start = Math.max(acc[i].start, other[j].start);
      const end = Math.min(acc[i].end, other[j].end);
      if (end > start) next.push({ start, end });
      if (acc[i].end < other[j].end) i++;
      else j++;
    }
    acc = next;
  }
  return acc.map(out);
}

/** Bookable slot starts of `durationMinutes` inside free intervals, every `stepMinutes` on the clock (local). */
export function slotsIn(free: readonly Interval[], { durationMinutes = 30, stepMinutes = durationMinutes }: { durationMinutes?: number; stepMinutes?: number } = {}): Date[] {
  const step = stepMinutes * 60_000;
  const dur = durationMinutes * 60_000;
  const slots: Date[] = [];
  for (const f of free.map(ms)) {
    const offset = new Date(f.start).getTimezoneOffset() * 60_000;
    let t = Math.ceil((f.start - offset) / step) * step + offset;
    for (; t + dur <= f.end; t += step) slots.push(new Date(t));
  }
  return slots;
}

/**
 * Local-time date math for calendar-core. The names and semantics match date-fns
 * (`addDays`, `startOfWeek({ weekStartsOn })`, `differenceInCalendarDays` …) so this file can
 * be swapped for `date-fns` imports one-for-one. Every function returns a new Date.
 */

export type WeekStart = 0 | 1 | 2 | 3 | 4 | 5 | 6;

const clone = (d: Date | number) => new Date(typeof d === "number" ? d : d.getTime());

export function startOfDay(d: Date | number): Date {
  const x = clone(d);
  x.setHours(0, 0, 0, 0);
  return x;
}
export function endOfDay(d: Date | number): Date {
  const x = clone(d);
  x.setHours(23, 59, 59, 999);
  return x;
}
/** Calendar days, so a DST change keeps the wall-clock time. */
export function addDays(d: Date | number, n: number): Date {
  const x = clone(d);
  x.setDate(x.getDate() + n);
  return x;
}
export const addWeeks = (d: Date | number, n: number) => addDays(d, n * 7);
/** Clamps to the last day of a shorter month (31 Jan + 1 month → 28/29 Feb), like date-fns. */
export function addMonths(d: Date | number, n: number): Date {
  const x = clone(d);
  const day = x.getDate();
  x.setDate(1);
  x.setMonth(x.getMonth() + n);
  x.setDate(Math.min(day, getDaysInMonth(x)));
  return x;
}
export function addMinutes(d: Date | number, n: number): Date {
  return new Date(clone(d).getTime() + n * 60_000);
}
export function getDaysInMonth(d: Date | number): number {
  const x = clone(d);
  return new Date(x.getFullYear(), x.getMonth() + 1, 0).getDate();
}
export function startOfMonth(d: Date | number): Date {
  const x = startOfDay(d);
  x.setDate(1);
  return x;
}
export function endOfMonth(d: Date | number): Date {
  const x = startOfMonth(d);
  x.setMonth(x.getMonth() + 1, 0);
  return endOfDay(x);
}
export function startOfWeek(d: Date | number, { weekStartsOn = 0 }: { weekStartsOn?: WeekStart } = {}): Date {
  const x = startOfDay(d);
  const diff = (x.getDay() - weekStartsOn + 7) % 7;
  return addDays(x, -diff);
}
export function endOfWeek(d: Date | number, options: { weekStartsOn?: WeekStart } = {}): Date {
  return endOfDay(addDays(startOfWeek(d, options), 6));
}
export const isSameDay = (a: Date | number, b: Date | number) => startOfDay(a).getTime() === startOfDay(b).getTime();
export function isSameMonth(a: Date | number, b: Date | number): boolean {
  const x = clone(a);
  const y = clone(b);
  return x.getFullYear() === y.getFullYear() && x.getMonth() === y.getMonth();
}
export const isWeekend = (d: Date | number) => {
  const day = clone(d).getDay();
  return day === 0 || day === 6;
};
/** Whole calendar days from `b` to `a` (a − b), ignoring time of day and DST. */
export function differenceInCalendarDays(a: Date | number, b: Date | number): number {
  const x = startOfDay(a);
  const y = startOfDay(b);
  const utc = (d: Date) => Date.UTC(d.getFullYear(), d.getMonth(), d.getDate());
  return Math.round((utc(x) - utc(y)) / 86_400_000);
}
export const isBefore = (a: Date | number, b: Date | number) => clone(a).getTime() < clone(b).getTime();
export const isAfter = (a: Date | number, b: Date | number) => clone(a).getTime() > clone(b).getTime();
export const min = (a: Date, b: Date) => (a.getTime() <= b.getTime() ? a : b);
export const max = (a: Date, b: Date) => (a.getTime() >= b.getTime() ? a : b);

/** `YYYY-MM-DD` in local time: a stable React key and `data-date` for a day cell. */
export function toDayKey(d: Date | number): string {
  const x = clone(d);
  const p = (n: number) => String(n).padStart(2, "0");
  return `${x.getFullYear()}-${p(x.getMonth() + 1)}-${p(x.getDate())}`;
}
/** Local midnight of a `YYYY-MM-DD` key. */
export function fromDayKey(key: string): Date {
  const [y, m, d] = key.split("-").map(Number);
  return new Date(y, m - 1, d);
}

/** The locale's first day of the week (Intl `weekInfo` where supported), else Monday, or Sunday for en-US. */
export function localeWeekStart(locale?: string): WeekStart {
  try {
    const loc = new Intl.Locale(locale ?? Intl.DateTimeFormat().resolvedOptions().locale) as Intl.Locale & {
      weekInfo?: { firstDay: number };
      getWeekInfo?: () => { firstDay: number };
    };
    const info = loc.getWeekInfo?.() ?? loc.weekInfo;
    if (info) return (info.firstDay % 7) as WeekStart;
    return loc.region === "US" || loc.baseName === "en" ? 0 : 1;
  } catch {
    return 1;
  }
}

import {
  addDays,
  addMinutes,
  differenceInCalendarDays,
  endOfMonth,
  isSameDay,
  isSameMonth,
  isWeekend,
  startOfDay,
  startOfMonth,
  startOfWeek,
  toDayKey,
  type WeekStart,
} from "./dates";

export type CalendarDay = {
  date: Date;
  /** `YYYY-MM-DD`, local: key cells by it. */
  key: string;
  /** Day of month, 1–31. */
  day: number;
  /** 0 Sunday … 6 Saturday. */
  weekday: number;
  /** False for the leading/trailing days of neighbouring months in a month grid. */
  inMonth: boolean;
  isToday: boolean;
  isWeekend: boolean;
};

export type GridOptions = {
  /** 0 Sunday … 6 Saturday. Default 1 (Monday); `localeWeekStart(locale)` reads the locale's. */
  weekStartsOn?: WeekStart;
  /** "Today", for the today mark. Pass a fixed date for deterministic demos; default none. */
  today?: Date | number;
  locale?: string;
};

const dayOf = (date: Date, month: Date | null, today: Date | number | undefined): CalendarDay => ({
  date,
  key: toDayKey(date),
  day: date.getDate(),
  weekday: date.getDay(),
  inMonth: month ? isSameMonth(date, month) : true,
  isToday: today !== undefined && isSameDay(date, today),
  isWeekend: isWeekend(date),
});

/** Weekday headers in display order: `{ narrow: "M", short: "Mon", long: "Monday" }`. */
export function weekdays({ weekStartsOn = 1, locale }: Pick<GridOptions, "weekStartsOn" | "locale"> = {}) {
  // 4 Jan 1970 was a Sunday.
  const base = new Date(1970, 0, 4 + weekStartsOn);
  const f = (weekday: "narrow" | "short" | "long") => new Intl.DateTimeFormat(locale, { weekday });
  const [n, s, l] = [f("narrow"), f("short"), f("long")];
  return Array.from({ length: 7 }, (_, i) => {
    const d = addDays(base, i);
    return { weekday: d.getDay(), narrow: n.format(d), short: s.format(d), long: l.format(d) };
  });
}

/**
 * A month as weeks of days, padded with the neighbouring months' days. `fixedWeeks` (default
 * true) always returns six weeks, so paging months never changes the grid's height.
 *
 *   const { title, weeks, weekdays } = monthGrid(new Date(2026, 9), { today: FIXTURE_NOW });
 */
export function monthGrid(month: Date | number, { weekStartsOn = 1, today, locale, fixedWeeks = true }: GridOptions & { fixedWeeks?: boolean } = {}) {
  const first = startOfMonth(month);
  const start = startOfWeek(first, { weekStartsOn });
  const span = differenceInCalendarDays(endOfMonth(first), start) + 1;
  const weekCount = fixedWeeks ? 6 : Math.ceil(span / 7);
  const weeks: CalendarDay[][] = Array.from({ length: weekCount }, (_, w) => Array.from({ length: 7 }, (_, d) => dayOf(addDays(start, w * 7 + d), first, today)));
  return {
    title: new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" }).format(first),
    month: first,
    weeks,
    days: weeks.flat(),
    weekdays: weekdays({ weekStartsOn, locale }),
    start,
    end: addDays(start, weekCount * 7 - 1),
  };
}

export type TimeGridOptions = GridOptions & {
  /** Days shown. Default 7 (a week grid); 5 for a work week; 1 for a day. */
  days?: number;
  /** First and last hour shown (end exclusive). Default 8 → 20. */
  startHour?: number;
  endHour?: number;
  /** Slot length. Default 30. */
  slotMinutes?: number;
  /** Start on `anchor` itself instead of its week start (day views, rolling 3-day views). */
  fromAnchor?: boolean;
};

export type TimeSlot = {
  index: number;
  /** Minutes after midnight. */
  minutes: number;
  /** Localised label ("09:00" or "9 AM"), on whole hours only; empty otherwise. */
  label: string;
  hourStart: boolean;
};

/**
 * A week (or day) time grid: day columns and time slots, plus `slotStart(day, slot)` to turn
 * a cell back into a Date. The basis of Week Calendar, Tour and Interview Schedulers.
 */
export function timeGrid(anchor: Date | number, options: TimeGridOptions = {}) {
  const { weekStartsOn = 1, today, locale, days = 7, startHour = 8, endHour = 20, slotMinutes = 30, fromAnchor = false } = options;
  const first = fromAnchor ? startOfDay(anchor) : startOfWeek(anchor, { weekStartsOn });
  const dayList = Array.from({ length: days }, (_, i) => dayOf(addDays(first, i), null, today));
  const hourFmt = new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" });
  const slotCount = Math.max(0, Math.round(((endHour - startHour) * 60) / slotMinutes));
  const slots: TimeSlot[] = Array.from({ length: slotCount }, (_, index) => {
    const minutes = startHour * 60 + index * slotMinutes;
    const hourStart = minutes % 60 === 0;
    return { index, minutes, hourStart, label: hourStart ? hourFmt.format(new Date(1970, 0, 1, minutes / 60)) : "" };
  });
  const last = dayList[dayList.length - 1]?.date ?? first;
  const rangeFmt = new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", year: "numeric" });
  return {
    title: days === 1 ? new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long" }).format(first) : rangeFmt.formatRange(first, last),
    days: dayList,
    slots,
    slotMinutes,
    startHour,
    endHour,
    /** The Date a cell starts at. */
    slotStart: (dayIndex: number, slotIndex: number) => addMinutes(startOfDay(dayList[dayIndex].date), startHour * 60 + slotIndex * slotMinutes),
    /** The cell a Date falls in, or null when it is outside the grid. */
    cellOf: (t: Date | number) => {
      const d = new Date(t);
      const dayIndex = dayList.findIndex((x) => isSameDay(x.date, d));
      const m = d.getHours() * 60 + d.getMinutes() - startHour * 60;
      if (dayIndex < 0 || m < 0 || m >= slotCount * slotMinutes) return null;
      return { dayIndex, slotIndex: Math.floor(m / slotMinutes) };
    },
  };
}

export type TimedItem = { id: string; start: Date | number; end: Date | number };

export type PlacedItem<T> = {
  item: T;
  /** 0–1 share of the visible hours: `top: ${top * 100}%`. */
  top: number;
  height: number;
  /** Side-by-side columns for overlapping items. */
  column: number;
  columns: number;
};

/**
 * Places one day's timed items (appointments, shifts, tours) on a time grid: top and height as
 * shares of the visible hours (clipped to them), and overlapping items in side-by-side columns
 * whose count is per cluster, not per day.
 */
export function placeDayItems<T extends TimedItem>(items: readonly T[], day: Date | number, { startHour = 8, endHour = 20 }: { startHour?: number; endHour?: number } = {}): PlacedItem<T>[] {
  const dayStart = startOfDay(day).getTime();
  const lo = dayStart + startHour * 3_600_000;
  const hi = dayStart + endHour * 3_600_000;
  const span = hi - lo;
  const visible = items
    .map((item) => ({ item, s: Math.max(lo, +new Date(item.start)), e: Math.min(hi, +new Date(item.end)) }))
    .filter((x) => x.e > x.s)
    .sort((a, b) => a.s - b.s || b.e - a.e);
  const out: PlacedItem<T>[] = [];
  let cluster: { x: (typeof visible)[number]; column: number }[] = [];
  let clusterEnd = -Infinity;
  const flush = () => {
    const columns = Math.max(1, ...cluster.map((c) => c.column + 1));
    for (const c of cluster) out.push({ item: c.x.item, top: (c.x.s - lo) / span, height: (c.x.e - c.x.s) / span, column: c.column, columns });
    cluster = [];
  };
  for (const x of visible) {
    if (x.s >= clusterEnd) {
      flush();
      clusterEnd = -Infinity;
    }
    const taken = new Set(cluster.filter((c) => c.x.e > x.s).map((c) => c.column));
    let column = 0;
    while (taken.has(column)) column++;
    cluster.push({ x, column });
    clusterEnd = Math.max(clusterEnd, x.e);
  }
  flush();
  return out;
}

/**
 * Items bucketed by the local days they touch, for month grids: a three-day leave shows on
 * each of its days. Keys are `YYYY-MM-DD`.
 */
export function itemsByDay<T extends TimedItem>(items: readonly T[]): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const item of items) {
    const s = startOfDay(item.start);
    // An item ending exactly at midnight doesn't touch that day; a zero-length item still shows on its day.
    const days = Math.max(0, differenceInCalendarDays(+new Date(item.end) - 1, s));
    for (let i = 0; i <= days; i++) {
      const k = toDayKey(addDays(s, i));
      const list = map.get(k);
      if (list) list.push(item);
      else map.set(k, [item]);
    }
  }
  return map;
}

"use client";

import { useCallback, useEffect, useState, type KeyboardEvent, type PointerEvent } from "react";
import { addDays, addMinutes, differenceInCalendarDays, startOfDay, toDayKey } from "./dates";

/** Whole days (bookings, leave, deadlines) or fixed-length time slots (tours, shifts). */
export type Granularity = "day" | { minutes: number };

/** An inclusive range of units: `end` is the last selected day, or the start of the last selected slot. */
export type DateRange = { start: Date; end: Date };

const isDay = (g: Granularity): g is "day" => g === "day";
const unitStart = (d: Date | number, g: Granularity) => {
  if (isDay(g)) return startOfDay(d);
  const ms = g.minutes * 60_000;
  const t = +new Date(d);
  const local = t - new Date(t).getTimezoneOffset() * 60_000;
  return new Date(t - (((local % ms) + ms) % ms));
};
const unitAdd = (d: Date, n: number, g: Granularity) => (isDay(g) ? addDays(d, n) : addMinutes(d, n * g.minutes));
const unitDiff = (a: Date, b: Date, g: Granularity) => (isDay(g) ? differenceInCalendarDays(a, b) : Math.round((+a - +b) / (g.minutes * 60_000)));
const sameUnit = (a: Date, b: Date, g: Granularity) => unitDiff(a, b, g) === 0;

/** Orders two dates into a range, snapped to whole units. */
export function normalizeRange(a: Date | number, b: Date | number, granularity: Granularity = "day"): DateRange {
  const x = unitStart(a, granularity);
  const y = unitStart(b, granularity);
  return +x <= +y ? { start: x, end: y } : { start: y, end: x };
}

/** Units in a range, inclusive: a one-night booking selected as two days is 2. */
export function rangeLength(r: DateRange, granularity: Granularity = "day"): number {
  return unitDiff(r.end, r.start, granularity) + 1;
}

export function isInRange(d: Date | number, r: DateRange | null | undefined, granularity: Granularity = "day"): boolean {
  if (!r) return false;
  const u = unitStart(d, granularity);
  return +u >= +r.start && +u <= +r.end;
}

export type RangePosition = "single" | "start" | "middle" | "end";

/** Where a cell sits in a range, for the pill shape: rounded ends, square middle. */
export function rangePosition(d: Date | number, r: DateRange | null | undefined, granularity: Granularity = "day"): RangePosition | null {
  if (!r || !isInRange(d, r, granularity)) return null;
  const u = unitStart(d, granularity);
  const s = sameUnit(u, r.start, granularity);
  const e = sameUnit(u, r.end, granularity);
  return s && e ? "single" : s ? "start" : e ? "end" : "middle";
}

export type RangeConstraints = {
  granularity?: Granularity;
  /** Units that can't be selected (booked nights, weekends, past days). A range never spans one. */
  isDisabled?: (d: Date) => boolean;
  /** Fewest units in a committed range. Default 1. */
  minLength?: number;
  /** Most units. Default unlimited. */
  maxLength?: number;
};

/**
 * The range from `anchor` towards `target` that the constraints allow: it stops before the
 * first disabled unit (a stay can't span a booked night), caps at `maxLength`, and stretches
 * to `minLength` in the drag's direction when it can. Null when the anchor itself is disabled
 * or `minLength` can't be met.
 */
export function constrainRange(anchor: Date | number, target: Date | number, { granularity = "day", isDisabled, minLength = 1, maxLength = Infinity }: RangeConstraints = {}): DateRange | null {
  const a = unitStart(anchor, granularity);
  const t = unitStart(target, granularity);
  if (isDisabled?.(a)) return null;
  const dir = +t >= +a ? 1 : -1;
  const want = Math.max(minLength, Math.min(maxLength, Math.abs(unitDiff(t, a, granularity)) + 1));
  let end = a;
  let n = 1;
  while (n < want) {
    const next = unitAdd(end, dir, granularity);
    if (isDisabled?.(next)) break;
    end = next;
    n++;
  }
  if (n < minLength) return null;
  return normalizeRange(a, end, granularity);
}

export type UseRangeSelectionOptions = RangeConstraints & {
  /** Controlled committed range. */
  value?: DateRange | null;
  defaultValue?: DateRange | null;
  onChange?: (range: DateRange | null) => void;
};

export type CellState = {
  /** In the committed range. */
  selected: boolean;
  /** In the range being chosen (between the anchor and the pointer). */
  previewing: boolean;
  /** Position in whichever range is showing (the preview while choosing): drives the pill shape. */
  position: RangePosition | null;
  disabled: boolean;
  /** The first click / drag start of the range being chosen. */
  anchor: boolean;
};

type Pending = { anchor: Date | null; hover: Date | null; dragging: boolean; moved: boolean };
const idle: Pending = { anchor: null, hover: null, dragging: false, moved: false };

/**
 * Range selection for day grids and time grids. Click a start and an end, or press and drag
 * across cells (touch too: give the grid `touch-action: none`); Enter or Space on a focused cell
 * acts as a click, Escape cancels. While choosing, `preview` follows the pointer and respects
 * the constraints, so a guest sees exactly the stay they would get.
 *
 *   const sel = useRangeSelection({ isDisabled: (d) => booked.has(toDayKey(d)), maxLength: 14 });
 *   <button {...sel.cellProps(day.date)} data-position={sel.stateOf(day.date).position ?? undefined} />
 */
export function useRangeSelection(options: UseRangeSelectionOptions = {}) {
  const { value: controlled, defaultValue = null, onChange, granularity = "day", isDisabled, minLength, maxLength } = options;
  const [uncontrolled, setUncontrolled] = useState<DateRange | null>(defaultValue);
  const [pending, setPending] = useState<Pending>(idle);
  const value = controlled !== undefined ? controlled : uncontrolled;
  const constraints: RangeConstraints = { granularity, isDisabled, minLength, maxLength };

  const commit = (range: DateRange | null) => {
    if (controlled === undefined) setUncontrolled(range);
    onChange?.(range);
    setPending(idle);
  };

  const preview = pending.anchor ? constrainRange(pending.anchor, pending.hover ?? pending.anchor, constraints) : null;

  /** A click (or Enter/Space): starts a range, or ends the one being chosen. */
  const select = (d: Date) => {
    if (isDisabled?.(unitStart(d, granularity))) return;
    if (!pending.anchor) return setPending({ anchor: unitStart(d, granularity), hover: null, dragging: false, moved: false });
    const range = constrainRange(pending.anchor, d, constraints);
    if (range) commit(range);
  };
  const hover = (d: Date | null) => setPending((p) => (p.anchor ? { ...p, hover: d, moved: p.moved || (d !== null && !sameUnit(d, p.anchor, granularity)) } : p));
  const cancel = () => setPending(idle);
  const clear = () => commit(null);

  // A drag that ends outside the grid still ends.
  const dragging = pending.dragging;
  const endDrag = useCallback(() => {
    setPending((p) => (p.dragging ? { ...p, dragging: false } : p));
  }, []);
  useEffect(() => {
    if (!dragging) return;
    window.addEventListener("pointerup", endDrag);
    window.addEventListener("pointercancel", endDrag);
    return () => {
      window.removeEventListener("pointerup", endDrag);
      window.removeEventListener("pointercancel", endDrag);
    };
  }, [dragging, endDrag]);

  const cellProps = (date: Date) => ({
    "data-date": isDay(granularity) ? toDayKey(date) : unitStart(date, granularity).toISOString(),
    "aria-selected": isInRange(date, value, granularity),
    "aria-disabled": isDisabled?.(unitStart(date, granularity)) || undefined,
    onPointerDown: (e: PointerEvent<HTMLElement>) => {
      if (e.button !== 0) return;
      // Release touch's implicit capture so the cells under the finger get pointerenter.
      if (e.currentTarget.hasPointerCapture?.(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId);
      if (pending.anchor && !pending.dragging) return select(date);
      if (isDisabled?.(unitStart(date, granularity))) return;
      setPending({ anchor: unitStart(date, granularity), hover: date, dragging: true, moved: false });
    },
    onPointerEnter: () => {
      if (pending.anchor) hover(date);
    },
    onPointerUp: () => {
      if (!pending.dragging || !pending.anchor) return;
      // A press without movement leaves the anchor for click-click; a drag commits.
      if (!pending.moved && sameUnit(date, pending.anchor, granularity)) return setPending((p) => ({ ...p, dragging: false }));
      const range = constrainRange(pending.anchor, date, constraints);
      if (range) commit(range);
      else cancel();
    },
    onKeyDown: (e: KeyboardEvent<HTMLElement>) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        select(date);
      } else if (e.key === "Escape" && pending.anchor) {
        e.preventDefault();
        cancel();
      }
    },
    onFocus: () => {
      if (pending.anchor) hover(date);
    },
  });

  const stateOf = (date: Date): CellState => {
    const showing = preview ?? value;
    return {
      selected: isInRange(date, value, granularity),
      previewing: isInRange(date, preview, granularity),
      position: rangePosition(date, showing, granularity),
      disabled: !!isDisabled?.(unitStart(date, granularity)),
      anchor: !!pending.anchor && sameUnit(date, pending.anchor, granularity),
    };
  };

  return { value, preview, anchor: pending.anchor, selecting: !!pending.anchor, select, hover, cancel, clear, setValue: commit, cellProps, stateOf };
}

/**
 * The date a roving-focus grid moves to for a key (WAI-ARIA date grid): arrows ±1 day / ±1
 * week, Home/End to the week's ends, PageUp/PageDown ±1 month (Shift: ±1 year). Null for other keys.
 */
export function nextFocusDate(date: Date, key: string, { weekStartsOn = 1, shift = false }: { weekStartsOn?: number; shift?: boolean } = {}): Date | null {
  const month = (n: number) => {
    const d = new Date(date);
    const day = d.getDate();
    d.setDate(1);
    d.setMonth(d.getMonth() + n);
    d.setDate(Math.min(day, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
    return d;
  };
  const offset = (date.getDay() - weekStartsOn + 7) % 7;
  switch (key) {
    case "ArrowLeft":
      return addDays(date, -1);
    case "ArrowRight":
      return addDays(date, 1);
    case "ArrowUp":
      return addDays(date, -7);
    case "ArrowDown":
      return addDays(date, 7);
    case "Home":
      return addDays(date, -offset);
    case "End":
      return addDays(date, 6 - offset);
    case "PageUp":
      return month(shift ? -12 : -1);
    case "PageDown":
      return month(shift ? 12 : 1);
    default:
      return null;
  }
}
